import{_ as o,l as r,o as n,c as l,v as a,p as m,x as i,d as s,i as h,S as g}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Lightning Attention","description":"","frontmatter":{"title":"Lightning Attention","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lightning-attention.md","filePath":"llm/lightning-attention.md","lastUpdated":1789023840000}'),p={name:"llm/lightning-attention.md"};function d(A,t,u,c,L,x){const e=r("Mermaid");return n(),l("div",null,[t[1]||(t[1]=a('<h1 id="lightning-attention" tabindex="-1">Lightning Attention <a class="header-anchor" href="#lightning-attention" aria-label="Permalink to &quot;Lightning Attention&quot;">​</a></h1><div class="epigraph"><p>因果情形下的 cumsum 挡住了线性注意力的理论速度；把块内交给左乘、块间交给右乘，训练吞吐才能不随长度塌下去。</p><footer>—— Qin, Sun, Li, Shen, Sun, Zhong, Lightning Attention-2, 2024</footer></div><p><a href="/llm/linear-attention">Linear Attention</a> 写出核化与结合律：<a href="/llm/katharopoulos-linear">Katharopoulos 原文</a> 证明因果形式是 RNN。墙钟上，因果线性核常被前缀和拖住，理论 \\(O(nd^2)\\) 到不了恒定步时。<a href="/llm/minimax-text01">MiniMax-Text-01</a> 把 Lightning Attention 用到百万上下文，那是产品级混合架构；本篇写 Qin 等人的核本身：Lightning Attention-2 如何用分块消掉因果 cumsum，以及 Lightning Attention-1 只解决了 IO、还没解决复杂度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性注意力把 \\(\\mathrm{softmax}(QK^\\top)V\\) 换成可结合的 \\(\\phi(Q)(\\phi(K)^\\top V)\\)。非因果时右乘先把 \\(K^\\top V\\) 收成 \\(d\\times d\\)，再左乘 \\(Q\\)，长度方向线性。因果时每个位置的状态是前缀，朴素右乘需要 cumsum，难以整段落成 Tensor Core 上的大 GEMM。Lightning Attention-1（Qin 等人在 TransNormerLLM 里的 IO 感知实现）学习 FlashAttention 的切块：把 \\(Q,K,V\\) 搬进 SRAM 再算，访存友好，但块内仍走左乘，整体仍近 \\(O(n^2 d)\\)，长度一长 TGS 就掉。</p><p>FlashAttention-2 把 softmax 注意力的墙钟打得很满，长度增加时 TGS 仍下降。线性方法若不能给出「固定显存下吞吐几乎不随 \\(n\\) 变」的曲线，就无法兑现「无限长」的广告。问题是算法的：如何在因果约束下既保留块间的右乘，又在块内用硬件喜欢的左乘。</p><p><span class="marginnote">「无限长」在原文里立刻加了硬件限定：显存仍限制激活与优化器状态。恒定的是<em>给定显存预算下的逐步训练速度</em>，不是真的能在一张卡上放任意 \\(n\\)。</span></p><h3 id="transnormer-的-normattention-是宿主" tabindex="-1">TransNormer 的 NormAttention 是宿主 <a class="header-anchor" href="#transnormer-的-normattention-是宿主" aria-label="Permalink to &quot;TransNormer 的 NormAttention 是宿主&quot;">​</a></h3><p>Qin 等人 2022 年的 TransNormer 用</p> \\[O=\\mathrm{Norm}((QK^\\top)V)=\\mathrm{Norm}(Q(K^\\top V)) \\]<p>去掉 softmax 与缩放，归一放在后面。Lightning 核服务的是这类线性（或带衰减的线性）形式，不是把 FA 的 softmax 变得线性。MiniMax 后来每隔七层插一层 softmax，是因为纯线性检索弱；那是架构分工，核论文的主指标是速度随长度是否平坦。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="块内左乘、块间右乘" tabindex="-1">块内左乘、块间右乘 <a class="header-anchor" href="#块内左乘、块间右乘" aria-label="Permalink to &quot;块内左乘、块间右乘&quot;">​</a></h3><p>把序列切成大小 \\(B\\) 的块。第 \\(i\\) 块的输出拆成：块内因果注意力（左乘 \\(Q_iK_i^\\top\\) 再乘 \\(V_i\\)，块小，二次可接受）加上块间贡献（用已经累积的 \\(KV\\) 状态右乘 \\(Q_i\\)）。块结束后用本块的 \\(K_i,V_i\\) 更新状态。衰减 \\(\\lambda\\) 可以乘进状态，对应 RetNet / Lightning 里数据无关的遗忘。前向与反向都做同样的切块，中间 \\(KV\\) 留在 SRAM 里累加，减少 HBM 往返。实现用 Triton。</p><p>相对 Lightning-1，复杂度在 \\(n\\gg B\\) 时由块间线性项主导；相对朴素 cumsum，没有一条沿全长的串行前缀依赖挡着 GEMM。作者在 400M / 1B / 3B 上画 TGS：Lightning-2 几乎不随序列变长而掉，FA2 与 Lightning-1 明显下降。</p><h3 id="与分块线性注意力的关系" tabindex="-1">与分块线性注意力的关系 <a class="header-anchor" href="#与分块线性注意力的关系" aria-label="Permalink to &quot;与分块线性注意力的关系&quot;">​</a></h3><p>Hua 等人、Sun 等人、Yang 等人的 chunkwise 线性注意力是同一思想家族：块间传状态、块内用并行形式。Lightning-2 的表述强调 IO 与因果 cumsum，宿主是 TransNormer 的 NormAttention；GLA / Mamba-2 的分块还要消化数据依赖衰减或 SSD 结构。读核时不要把 MiniMax 的混合比例写进 Qin 的算法节。</p>',17)),(n(),m(g,null,{default:i(()=>[h(e,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20QKV%5B%22Q%20K%20V%20%E5%88%87%E5%9D%97%E8%BF%9B%20SRAM%22%5D%20--%3E%20INTRA%5B%22%E5%9D%97%E5%86%85%EF%BC%9A%E5%B7%A6%E4%B9%98%E5%9B%A0%E6%9E%9C%20QK%E1%B5%80V%22%5D%0A%20%20QKV%20--%3E%20INTER%5B%22%E5%9D%97%E9%97%B4%EF%BC%9A%E5%8F%B3%E4%B9%98%20Q%C2%B7(KV%20%E7%8A%B6%E6%80%81)%22%5D%0A%20%20INTER%20--%3E%20KV%5B%22%E6%9B%B4%E6%96%B0%20KV%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20INTRA%20--%3E%20SUM%5B%22%E7%9B%B8%E5%8A%A0%E5%90%8E%E5%86%99%E5%9B%9E%20HBM%22%5D%0A%20%20KV%20--%3E%20SUM%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为什么因果会逼出-cumsum" tabindex="-1">为什么因果会逼出 cumsum <a class="header-anchor" href="#为什么因果会逼出-cumsum" aria-label="Permalink to &quot;为什么因果会逼出 cumsum&quot;">​</a></h3><p>非因果的 \\(K^\\top V\\) 是一个全局矩阵，所有查询共享。因果要求位置 \\(t\\) 只能看见 \\(s\\le t\\)，等价于对每个 \\(t\\) 有不同的前缀和。直接物化前缀是 \\(O(n)\\) 个 \\(d\\times d\\) 矩阵，要么串行，要么用扫描但把状态写到 HBM。分块把「前缀」粗化成块级状态：块间是扫描，块内用下三角稠密注意力替代细粒度前缀。\\(B\\) 取 64/128 一类 tile 时，块内二次被 SRAM 吃掉，块间扫描步数是 \\(n/B\\)。</p><p>衰减使远块贡献指数下降，数值上接近局部，但计算仍扫过所有块状态。这与 softmax 滑窗不同：滑窗物理上不读窗外 KV；线性衰减是读压缩过的状态。检索能力弱于 softmax，是 <a href="/llm/linear-rnn-vs-attention">线性 RNN 与注意力分工</a> 里那条界，不是核写错了。</p><p><span class="marginnote">图 1 的对照是 LLaMA+FA2 对 TransNormerLLM+Lightning。架构不完全相同，平坦曲线证明的是<em>该线性核</em>的长度缩放，不能直接读成「换核即可让 LLaMA 质量不变、速度恒定」。</span></p><h3 id="从核到-minimax-的距离" tabindex="-1">从核到 MiniMax 的距离 <a class="header-anchor" href="#从核到-minimax-的距离" aria-label="Permalink to &quot;从核到 MiniMax 的距离&quot;">​</a></h3><p><em>Various Lengths, Constant Speed</em>（Qin 等人，arXiv:2405.17381）把 Lightning Attention 配上 TransNormerLLM：SimpleRMSNorm、LRPE 等。MiniMax-01 再把它放进 4560 亿 MoE、七层线性加一层 softmax。百万上下文是系统工程（混合层、并行、数据）而不只是 Triton 核。本篇只要求记住：没有块间右乘，线性注意力在因果训练里会先输给 FA 的墙钟，理论复杂度帮不上忙。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Lightning 不恢复 softmax 的尖峰拷贝。纯线性栈在针测与精确检索上通常要混层。衰减 \\(\\lambda\\) 若全局固定，长程要么全忘要么全糊；数据依赖门控是 GLA / Mamba-2 / Gated DeltaNet 的主题。块大小 \\(B\\) 必须对齐 SRAM 与 Tensor Core；\\(B\\) 太大，块内二次又回来；\\(B\\) 太小，启动开销压过线性项。</p><p>不要与 FlashAttention 比「谁更准」——一个有 softmax，一个没有。比的是给定线性（或 NormAttention）公式时，墙钟是否随 \\(n\\) 平坦。也不要把 Lightning-2 写成对 softmax 的近似；它是线性核的 IO 算法。PyTorch 生态里更常见的线性训练栈是 Flash Linear Attention 库的分块核；选型看宿主架构，不是看名字谁更像闪电。</p><p>反向必须与前向同一套分块，否则因果线性的梯度会偷偷物化大矩阵。融合失败时，表现会退回 Lightning-1：访存好，复杂度仍近二次。</p><p>与 FlashAttention 的切块同构、对象不同：FA 在块内做在线 softmax 与统计量合并；Lightning-2 在块内做无 softmax 的左乘，块间做状态右乘。把 FA 的核直接套到线性公式上，会得到 Lightning-1 那种「切块但仍近二次」的东西。读代码时看块间是否维护 \\(KV\\) 状态，是区分两代 Lightning 的最快方法。</p><p><span class="marginnote">恒定速度假设 \\(d\\) 固定、核占满计算。极短序列上启动开销会让线性核慢于 FA。报 TGS 要给长度范围，不要只截长端的平坦段。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lightning Attention-2 用块内左乘、块间右乘，去掉因果线性注意力对全长 cumsum 的依赖。</li><li>Lightning-1 已是 IO 感知切块，但复杂度仍近二次；-2 才让 TGS 随长度近似恒定。</li><li>宿主是 TransNormer 一类去掉 softmax 的线性/归一注意力，不是 FA 的替换核。</li><li>MiniMax-01 的百万上下文建立在这套核与混合 softmax 层之上，细节见产品文。</li><li>检索精度仍受线性核限制；平坦吞吐不是免费的质量。</li><li>块大小、衰减与是否混层，决定从核论文到可用语言模型的距离。</li><li>出处：Qin et al.，<em>Lightning Attention-2</em>，arXiv:2401.04658；<em>Various Lengths, Constant Speed</em>，arXiv:2405.17381。</li></ul>',15))])}const B=o(p,[["render",d]]);export{f as __pageData,B as default};
